// 📁 src/app/pages/booking/booking.component.ts
// 🔄 MIGRADO: Property Booking → Room Booking + Establishment

import { Component, OnInit, OnDestroy } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Subject, combineLatest, Observable, of } from 'rxjs';
import { takeUntil, switchMap, map, tap, catchError, debounceTime } from 'rxjs/operators';

// ✅ NUEVOS IMPORTS - Room + Establishment
import { Room, RoomType } from '../../core/models/room.interface';
import { Establishment } from '../../core/models/establishment.interface';
import { RoomService } from '../../core/services/room.service';
import { EstablishmentService } from '../../core/services/establishment.service';

// ✅ MANTENER - Booking interfaces optimizadas
import { BookingService } from '../../core/services/booking.service';
import { 
  Booking, BookingRequest, PriceBreakdown, BookingProgress, 
  PartialBookingRequest, WhatsAppMessage 
} from '../../core/models/booking.interface';
import { 
  DayAvailability, DateSelection, CalendarMonth, DateValidationResult 
} from '../../core/models/calendar.interface';

@Component({
  selector: 'app-booking',
  templateUrl: './booking.component.html',
  styleUrls: ['./booking.component.scss']
})
export class BookingComponent implements OnInit, OnDestroy {
  
  // ================================
  // 🗂️ PROPIEDADES PRINCIPALES - MIGRADAS
  // ================================
  
  room: Room | null = null;                          // ✅ CAMBIO: property → room
  establishment: Establishment | null = null;       // ✅ NUEVO: establishment info
  currentBooking: PartialBookingRequest | null = null;
  bookingProgress: BookingProgress | null = null;
  priceBreakdown: PriceBreakdown | null = null;
  dateValidation: DateValidationResult | null = null;
  isLoading = true;
  isSubmitting = false;
  showCalendar = false;
  calendarMode: 'check-in' | 'check-out' = 'check-in';
  datesForm!: FormGroup;
  guestsForm!: FormGroup;
  detailsForm!: FormGroup;
  currentMonth: CalendarMonth | null = null;
  availableDaysInMonth: DayAvailability[] = [];
  selectedDates: DateSelection = {
    checkIn: null,
    checkOut: null,
    nights: 0,
    totalDays: 0,
    isValid: false,
    errors: [],
    warnings: [],
    weekendNights: 0,
    weekdayNights: 0,
    hasHolidays: false,
    applicableDiscounts: []
  };
  currentStep = 1;
  totalSteps = 4;
  canProceed = false;
  private stepValidations = {
    dates: false,
    guests: false, 
    details: false,
    review: false
  };

  private destroy$ = new Subject<void>();
  error: string | null = null;
  
  constructor(
    private route: ActivatedRoute,
    private router: Router,
    private fb: FormBuilder,
    private roomService: RoomService,              // ✅ CAMBIO: propertyService → roomService
    private establishmentService: EstablishmentService, // ✅ NUEVO: establishmentService
    private bookingService: BookingService
  ) {
    this.initializeForms();
  }

  // 📁 booking.component.ts - en ngOnInit()
ngOnInit(): void {
  console.log('🔍 Booking component initialized');
  console.log('🔍 Route params:', this.route.snapshot.paramMap.keys);
